import copy
import logging
import pprint
import threading
import time
from threading import Semaphore
from typing import Callable
from robot.api import logger as r_logger
from taf.ul.generic_tshark_json_parser.logger_config import configure_main_logger
from taf.ul.generic_tshark_json_parser.tshark_generic_source import GenericJsonTsharkSource
from taf.ul.generic_tshark_json_parser.submodule_ute_common_abstract_core.message import Message

SOURCES = {}


class generic_tshark_json_parser(object):
    ROBOT_LIBRARY_SCOPE: str = 'GLOBAL'
    ROBOT_LISTENER_API_VERSION: int = 2

    def __init__(self):
        self.ROBOT_LIBRARY_LISTENER = self
        self.logger = configure_main_logger('generic_tshark_json_parser.interface')
        self.records_awaited = None
        self.timeout = None
        self.expected_records = {}

    def _end_suite(self, name, attrs):
        self.logger.debug('End suite called')
        self.stop_all_json_sources()

    def create_json_source(self,
                           tshark_command: str = 'tshark -i any -T json -l',
                           source_alias: str = 'default',
                           start: bool = False,
                           protocol: str = None,
                           separete_protocol_parsing: bool = None,
                           meta_data: dict = None,
                           callback: Callable = None,
                           filter_as_string: str = None,
                           filter_as_query: str = None):
        assert source_alias not in SOURCES, f'Source with {source_alias} already created'
        source = GenericJsonTsharkSource(tshark_command=tshark_command,
                                         alias=source_alias,
                                         start=start,
                                         protocol=protocol,
                                         separete_protocol_parsing=separete_protocol_parsing,
                                         meta_data=meta_data,
                                         callback=callback,
                                         filter_as_string=filter_as_string,
                                         filter_as_query=filter_as_query)

        SOURCES[source_alias] = source
        self.logger.debug(f'Created json source: "{source_alias}" with command: "{tshark_command}".\n'
                          f'Current number of sources: {len(SOURCES)}')

    def set_tshark_command(self, *tshark_command, **params):
        if 'source_alias' not in params:
            source_alias = 'default'
        else:
            source_alias = params['source_alias']
        assert source_alias in SOURCES, f'Source with {source_alias} not created'
        tshark_cmd = " ".join(tshark_command)
        self.logger.debug(f'Supplied tshark command:\n{tshark_cmd}')
        SOURCES[source_alias].set_tshark_command(tshark_command=tshark_cmd)

    def set_protocol(self, protocol: str, source_alias: str = 'default'):
        assert source_alias in SOURCES, f'Source with {source_alias} not created'
        SOURCES[source_alias].set_protocol(protocol=protocol)

    def set_separate_records_for_each_protocol(self, source_alias: str = 'default'):
        assert source_alias in SOURCES, f'Source with {source_alias} not created'
        SOURCES[source_alias].set_divide_protocols()

    def set_meta_data(self, attribute_path_dict: dict, source_alias: str = 'default'):
        assert source_alias in SOURCES, f'Source with {source_alias} not created'
        SOURCES[source_alias].set_protocol(meta_data=attribute_path_dict)

    def set_filter_as_string(self, filter_as_string, source_alias: str = 'default'):
        assert source_alias in SOURCES, f'Source with {source_alias} not created'
        SOURCES[source_alias].set_filter_as_string(filter_as_string=filter_as_string)

    def set_filter_as_query(self, filter_as_query, source_alias: str = 'default'):
        assert source_alias in SOURCES, f'Source with {source_alias} not created'
        SOURCES[source_alias].set_filter_as_query(filter_as_query=filter_as_query)

    def start_json_source(self, source_alias: str = 'default'):
        assert source_alias in SOURCES, f'Source with {source_alias} not created'
        SOURCES[source_alias].start_source()
        self.logger.debug(f'Started json source with alias {source_alias}')

    def stop_json_source(self, source_alias: str = 'default'):
        global SOURCES
        assert source_alias in SOURCES, f'Source with {source_alias} not created'
        SOURCES[source_alias].stop_source()
        self.logger.debug(f'Stopped json source with alias {source_alias}')
        del SOURCES[source_alias]
        self.logger.debug(f'Removed source from active sources, remaining sources: {len(SOURCES)}')

    def pause_json_source(self, source_alias: str = 'default'):
        assert source_alias in SOURCES, f'Source with {source_alias} not created'
        SOURCES[source_alias].pause_source()
        self.logger.debug(f'Paused json source with alias {source_alias}')

    def play_json_source(self, source_alias: str = 'default'):
        assert source_alias in SOURCES, f'Source with {source_alias} not created'
        SOURCES[source_alias].play_source()
        self.logger.debug(f'Resumed json source with alias {source_alias}')

    def stop_all_json_sources(self):
        global SOURCES
        aliases = list(SOURCES.keys())
        self.logger.debug(f'Found {len(aliases)} active json sources')
        for alias in aliases:
            self.stop_json_source(source_alias=alias)
        self.logger.debug(f'Stoped all sources')
        SOURCES = {}

    def clear_records(self, source_alias=None):
        """

        :param source_alias:
        :return:
        """
        self.logger.debug('Clearing records for {}'
                          .format('all sources' if source_alias is None else 'for alias {}'.format(source_alias)))
        for source_alias in SOURCES:
            if source_alias is None or source_alias == source_alias:
                SOURCES[source_alias].clear_reccords()

    def get_records(self, source_alias=None, matching_query=None):
        """

        :param source_alias:
        :param matching_query:
        :return:
        """
        all_records = []
        for s_alias in SOURCES:
            if source_alias is None or source_alias == s_alias:
                self.logger.debug(f'Got {len(SOURCES[s_alias].records)} for {s_alias}')
                all_records.extend(SOURCES[s_alias].records)
        self.logger.debug(f'Found {len(all_records)} records')
        if matching_query is not None:
            self.logger.debug(f'Filtering records over query: {matching_query}')
            query_function = GenericJsonTsharkSource.generate_query_function(matching_query)
            filtered_records = [f_record for f_record in all_records if query_function(f_record) is True]
            print(f'Filtered {len(filtered_records)} records out of {len(all_records)} all record')
        else:
            filtered_records = all_records
        return copy.deepcopy(filtered_records)

    def record_object_fullfills_query(self, query, record_object):
        """

        :param query:
        :param record_object:
        :return:
        """
        query_function = GenericJsonTsharkSource.generate_query_function(query)
        assert isinstance(record_object, Message), \
            'Record must be a instance of ute_common_abstract_core.message.Message class'
        result = query_function(record_object)
        if not result:
            raise Exception(f'Record:\n{pprint.pformat(record_object)} did not fulfill query: {query}')

    def records_fullfill_query(self, query, condition='all', source_alias=None):
        """

        :param query:
        :param condition: allowed 'all' and 'any'
        :param source_alias: if not given, retrieves all stored records from sources
        :return:
        """
        allowed_conditions = ['all', 'any']
        assert condition in allowed_conditions, f'Only allowed conditions {allowed_conditions}'
        query_function = GenericJsonTsharkSource.generate_query_function(query)
        all_records = self.get_records(source_alias=source_alias)
        results = [query_function(record) for record in all_records]
        if not eval(condition)(results):
            for index, res in enumerate(results):
                if not res:
                    print(f'Record failed with query: \n{pprint.pformat(all_records[index])}')
            raise Exception(f'Records({len(all_records)}) did not fulfill condition: {condition} for query: {query}')

    def _on_timeout(self):
        self.records_awaited.release()
        self.timeout = True

    def wait_for_records(self, *queries, **options):
        """
        This is blocking! Will wait for records that will fulfill queries. Trigger for queries must happen in background.
        If user wants to expect some records, should use expect_for_records keyword.
        :param queries:
        :param options:
        :return:
        """
        self.logger.debug(f'Received {len(queries)} queries, will wait for {len(queries)} consecutive messages')
        alias = None if 'alias' not in options else options['source_alias']
        timeout = 30 if 'timeout' not in options else options['timeout']
        queries = list(queries)
        queries_funcs = [GenericJsonTsharkSource.generate_query_function(query) for query in queries]
        self.records_awaited = Semaphore(0)
        self.timeout = False
        callback_name = 'await_records'
        timer = threading.Timer(int(timeout), self._on_timeout)
        self.logger.debug(f'Left not fulfilled queries\n{queries}')

        def is_record_expected(record):
            if len(queries_funcs) and queries_funcs[0](record):
                self.logger.debug(f'Record:\n{pprint.pformat(record)}\n'
                                  f'accepted with query: {queries_funcs[0].string_query},'
                                  f' moving to next query on next record')
                queries_funcs.pop(0)
                self.logger.debug(f'Left {len(queries_funcs)} queries\n{queries[len(queries) - len(queries_funcs):]}')
                if len(queries_funcs) == 0:
                    self.records_awaited.release()
                    timer.cancel()
                    self.logger.debug('All queries fulfilled')

        start_t = time.time()
        for s_alias in SOURCES:
            if alias is None or alias == s_alias:
                SOURCES[s_alias].add_callback(callback_name, is_record_expected)
        timer.start()
        # if any([True if record.asn1per_record_name == record_name else False
        #         for record in self.get_all_pcmd_reports()]):
        #     print('Record: {} already present in history'.format(record_name))
        #     timer.cancel()
        #     self.pcmd_collector.remove_callback(callback_name)
        #     return
        self.logger.debug('Awaiting records')
        self.records_awaited.acquire()
        for s_alias in SOURCES:
            if alias is None or alias == s_alias:
                SOURCES[s_alias].remove_callback(callback_name)
        self.logger.debug('Awaiting records finished after: {}s'.format(time.time() - start_t))
        if self.timeout is True:
            raise Exception(f'Waiting for records timeout after:  {timeout}s,\n'
                            f' unmatched queries:\n'
                            f' {queries[len(queries) - len(queries_funcs):]}')

    def expect_for_records(self, *queries, **options):
        """
        This is non blocking! Will wait for records that will fulfill queries in background.
        :param queries:
        :param options:
        :return:
        """
        assert 'expect_alias' in options, 'You must give expect_alias parameter'
        alias = None if 'alias' not in options else options['source_alias']
        expect_alias = options['expect_alias']
        self.logger.debug(
            f'[expect:{expect_alias}]Received {len(queries)} queries '
            f' will wait for {len(queries)} consecutive messages')
        timeout = 30 if 'timeout' not in options else options['timeout']
        queries = list(queries)
        queries_funcs = [GenericJsonTsharkSource.generate_query_function(query) for query in queries]
        if expect_alias in self.expected_records:
            if self.expected_records[expect_alias]['result'] is False \
                    and self.expected_records[expect_alias]['timeout'] is False:
                raise Exception(f'Previous flow with alias: {expect_alias} has not yet completed.'
                                f'Use verify_that_records_occurred or use different expect_alias')
            else:
                self.logger.debug(f'Previous flow with alias: {expect_alias} already ended, overwriting')

        self.expected_records[expect_alias] = {'result': False, 'timeout': False,
                                               'semaphore': Semaphore(0),
                                               'timeout_value': timeout,
                                               'queries_func': queries_funcs,
                                               'queries': queries,
                                               'matched_records': []}
        callback_name = f'expect_records_{expect_alias}'
        self.logger.debug(f'[expect:{expect_alias}]Left not fulfilled queries\n\t{queries}')

        def _on_expect_timeout():
            self.expected_records[expect_alias]['result'] = False
            self.expected_records[expect_alias]['timeout'] = True
            self.expected_records[expect_alias]['semaphore'].release()
            self.logger.debug(f'Timeout reached')

        timer = threading.Timer(int(timeout), _on_expect_timeout)

        def is_record_expected(record):
            if len(queries_funcs) and queries_funcs[0](record):
                self.logger.debug(f'[expect:{expect_alias}]'
                                  f'Record:\n{pprint.pformat(record)}\n'
                                  f'accepted with query: {queries_funcs[0].string_query},'
                                  f' moving to next query on next record')
                self.expected_records[expect_alias]['matched_records'].append(record)
                queries_funcs.pop(0)
                self.logger.debug(f'[expect:{expect_alias}]'
                                  f'Left queries\n\t{queries[len(queries) - len(queries_funcs):]}')
                if len(queries_funcs) == 0:
                    self.expected_records[expect_alias]['result'] = True
                    self.expected_records[expect_alias]['semaphore'].release()
                    timer.cancel()
                    self.logger.debug('All queries fulfilled')

        for source_alias in SOURCES:
            if alias is None or alias == source_alias:
                SOURCES[source_alias].add_callback(callback_name, is_record_expected)
        timer.start()

    def verify_that_records_occurred(self, expect_alias, remove_flow=False):
        self.logger.debug(f'[expect:{expect_alias}]Awaiting records')
        assert expect_alias in self.expected_records, f'Such alias: {expect_alias} does not exist'
        self.expected_records[expect_alias]['semaphore'].acquire()
        self.logger.debug(f'[expect:{expect_alias}]Awaiting expected records ended')
        callback_name = f'expect_records_{expect_alias}'
        for source_alias in SOURCES:
            try:
                SOURCES[source_alias].remove_callback(callback_name)
            except Exception:
                pass
        self.logger.debug(f'[expect:{expect_alias}]Removed expect callback')
        if self.expected_records[expect_alias]['timeout'] is True:
            all_queries = len(self.expected_records[expect_alias]["queries"])
            left_unmatched_queries = len(self.expected_records[expect_alias]["queries_func"])
            raise Exception(f'[expect:{expect_alias}]Waiting for records timeout after:'
                            f' {self.expected_records[expect_alias]["timeout_value"]}s,\n'
                            f' unmatched queries:\n\t'
                            f' {self.expected_records[expect_alias]["queries"][all_queries - left_unmatched_queries:]}')
        self.logger.debug(f'[expect:{expect_alias}]Awaiting expected records ended successfully')
        if str(remove_flow).lower() == 'true':
            del self.expected_records[expect_alias]
            self.logger.debug(f'Removed flow: {expect_alias} from memory')

    def get_records_from_flow(self, expect_alias):
        assert expect_alias in self.expected_records, f'No flow with expect_alias: {expect_alias} found'
        if self.expected_records[expect_alias]['result'] is False \
                and self.expected_records[expect_alias]['timeout'] is False:
            self.logger.debug(f'Flow with alias: {expect_alias} has not yet completed.Waiting till the end')
            self.verify_that_records_occurred(expect_alias, remove_flow=False)
        else:
            self.logger.debug(f'Flow with alias: {expect_alias} already ended, getting records')
        return copy.deepcopy(self.expected_records[expect_alias]['matched_records'])
